const ids=["G01","G02","G03","G04","G05","G06"];
const res=await Promise.all(ids.map(id=>tools.origin_packet({case_id:id})));
const out=[];
for(let i=0;i<ids.length;i++){
  const c=res[i].cases[0];
  const ev=c.evidence;
  const map={};
  for(const e of ev.entries){ (map[e.evidence_id] ||= new Set()).add(e.source_id); }
  out.push({
    id:c.id,
    recorded_origin_count:ev.recorded_origin_count,
    independence:"unknown",
    queries:c.query_ids.map(q=>({material_id:q, origins:[...(map[q]||[])].sort()}))
  });
}
console.log(JSON.stringify({cases:out}));
